INSERT INTO knowledge (id, source_id, title, knowledge_type, core_idea, topics, confidence, importance, markdown_path, created_at, updated_at) VALUES ('KN-323562', 'SRC-323562', '8 Essential Markdown Documentation Files Before AI Vibe Coding', 'reel', 'Before writing or generating a single line of code with AI (''vibe coding''), establish a standardized documentation foundation of 8 markdown files to enforce context, architecture, and boundaries on the model.', '["Developer Tools & Automation", "AI Agents & Autonomous Systems", "Software Architecture & Backend", "Productivity & PKM Systems"]', 0.95, 9, 'vault/01 Knowledge/AI Agents & Autonomous Systems/KN-323562 - 8 Essential Markdown Documentation Files Before AI Vibe Coding.md', '2026-10-10T12:00:00.000Z', '2026-10-10T12:00:00.000Z');
INSERT INTO knowledge (id, source_id, title, knowledge_type, core_idea, topics, confidence, importance, markdown_path, created_at, updated_at) VALUES ('KN-947063', 'SRC-947063', 'The 8 Foundational Markdown Docs for Spec-Driven Vibe Coding', 'reel', 'Before writing code with AI or LLM coding assistants (''vibe coding''), establish a comprehensive 8-document repository blueprint (specs, architecture, design system, and agent rules) to provide full context and prevent AI hallucinations or architectural drift.', '["Developer Tools & Automation", "Vibe Coding", "Spec-Driven Development", "LLM Context Engineering", "Design Systems"]', 0.95, 9, 'vault/01 Knowledge/Artificial Intelligence & LLMs/KN-947063 - The 8 Foundational Markdown Docs for Spec-Driven Vibe Coding.md', '2026-10-10T12:00:00.000Z', '2026-10-10T12:00:00.000Z');
